import { Prism, languages, insertBefore } from '../prismCore'
import './javascript'

var flow = languages.flow = languages.extend('js', {});

insertBefore('flow', 'keyword', {
	'type': [
		{
			pattern: /\b(?:[Bb]oolean|Function|[Nn]umber|[Ss]tring|[Ss]ymbol|any|mixed|null|void)\b/,
			alias: 'class-name'
		}
	]
});
flow['function-variable'].pattern = /(?!\d)(?:(?!\s)[$\w\xA0-\uFFFF])+(?=\s*=\s*(?:function\b|(?:\([^()]*\)(?:\s*:\s*\w+)?|(?!\d)(?:(?!\s)[$\w\xA0-\uFFFF])+)\s*=>))/i;
delete flow['parameter'];

insertBefore('flow', 'operator', {
	'flow-punctuation': {
		pattern: /\{\||\|\}/,
		alias: 'punctuation'
	}
});

if (!Array.isArray(flow.keyword)) {
	flow.keyword = [flow.keyword];
}
flow.keyword.unshift(
	{
		pattern: /(^|[^$]\b)(?:Class|declare|opaque|type)\b(?!\$)/,
		lookbehind: true
	},
	{
		pattern: /(^|[^$]\B)\$(?:Diff|Enum|Exact|Keys|ObjMap|PropertyType|Record|Shape|Subtype|Supertype|await)\b(?!\$)/,
		lookbehind: true
	}
);
